from visual_reference import *
OUT=Path(sys.argv[1]);actual=np.array(Image.open(OUT/'snapshot-red.png').convert('RGBA'));h,w=actual.shape[:2];c={'bits':12,'min':0,'max':1,'vectorZoom':1,'matrix':'bt709'};rgb=source('bars',c);tifffile.imwrite(OUT/'snapshot-bars-source.tiff',rgb.astype(np.float32),photometric='rgb',compression='deflate');a=planes(rgb,c)[3];expected,_=reference(3,a,w,h,256*64);strength=np.maximum(0,expected.max(2).astype(float)-9)/246;alpha=np.rint(np.rint(strength*255)*.25);reference_rgba=np.zeros_like(actual);reference_rgba[:,:,:3]=[217,121,121];reference_rgba[:,:,3]=alpha;Image.fromarray(reference_rgba).save(OUT/'snapshot-red-expected.png');tifffile.imwrite(OUT/'snapshot-red-expected.tiff',reference_rgba.astype(np.uint16)*257,photometric='rgb',extrasamples='unassalpha',compression='deflate');actual_pm=actual[:,:,:3].astype(float)*actual[:,:,3:]/255;expected_pm=reference_rgba[:,:,:3].astype(float)*reference_rgba[:,:,3:]/255;err=np.abs(actual_pm-expected_pm);result={'max_premultiplied_rgb_error':float(err.max()),'max_alpha_error':float(abs(actual[:,:,3].astype(float)-alpha).max()),'visible_pixels':int((actual[:,:,3]>0).sum())};result['pass']=result['max_premultiplied_rgb_error']<=2 and result['max_alpha_error']<=2 and result['visible_pixels']>0;(OUT/'snapshot-comparison.json').write_text(json.dumps(result,indent=2));print(result);sys.exit(0 if result['pass'] else 1)
